document.addEventListener('DOMContentLoaded',function(){const mobileMenuBtn=document.querySelector('.mobile-menu-btn');const nav=document.querySelector('nav');const body=document.body;let overlay=document.querySelector('.overlay');if(!overlay){overlay=document.createElement('div');overlay.classList.add('overlay');document.body.appendChild(overlay)}if(mobileMenuBtn){mobileMenuBtn.addEventListener('click',function(e){e.stopPropagation();this.classList.toggle('active');nav.classList.toggle('active');overlay.classList.toggle('active');body.classList.toggle('menu-open')});overlay.addEventListener('click',function(){closeMenu()});document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeMenu()}})}function closeMenu(){if(mobileMenuBtn)mobileMenuBtn.classList.remove('active');if(nav)nav.classList.remove('active');if(overlay)overlay.classList.remove('active');body.classList.remove('menu-open')}const dropdownToggles=document.querySelectorAll('.has-dropdown > a');dropdownToggles.forEach(toggle=>{toggle.addEventListener('click',function(e){if(window.innerWidth<=992){e.preventDefault();e.stopPropagation();const parent=this.parentElement;dropdownToggles.forEach(otherToggle=>{const otherParent=otherToggle.parentElement;if(otherParent!==parent&&otherParent.classList.contains('active')){otherParent.classList.remove('active')}});parent.classList.toggle('active')}})});const userDropdown=document.querySelector('.user-dropdown > a');if(userDropdown){userDropdown.addEventListener('click',function(e){if(window.innerWidth>992){e.preventDefault();e.stopPropagation();this.parentElement.classList.toggle('show-dropdown');document.addEventListener('click',function closeDropdown(evt){if(!evt.target.closest('.user-dropdown')){userDropdown.parentElement.classList.remove('show-dropdown');document.removeEventListener('click',closeDropdown)}})}})}initScrollHeader();setupAnimations();setupCardEffects();const forms=document.querySelectorAll('form');forms.forEach(form=>{form.addEventListener('submit',function(e){const requiredFields=form.querySelectorAll('[required]');let hasErrors=false;requiredFields.forEach(field=>{if(!field.value.trim()){hasErrors=true;field.classList.add('error');if(!field.nextElementSibling||!field.nextElementSibling.classList.contains('error-message')){const errorMessage=document.createElement('div');errorMessage.classList.add('error-message');errorMessage.textContent='Это поле обязательно для заполнения';field.parentNode.insertBefore(errorMessage,field.nextSibling)}}else{field.classList.remove('error');if(field.nextElementSibling&&field.nextElementSibling.classList.contains('error-message')){field.nextElementSibling.remove()}}});if(hasErrors){e.preventDefault()}})});animateOnScroll();window.addEventListener('scroll',animateOnScroll)});function initScrollHeader(){const header=document.querySelector('header');let lastScrollTop=0;window.addEventListener('scroll',function(){let scrollTop=window.pageYOffset||document.documentElement.scrollTop;if(scrollTop>lastScrollTop&&scrollTop>150){header.classList.add('header-hidden')}else{header.classList.remove('header-hidden')}if(scrollTop>50){header.classList.add('scrolled')}else{header.classList.remove('scrolled')}lastScrollTop=scrollTop},false)}function setupAnimations(){const articleCards=document.querySelectorAll('.article-card');const categoryCards=document.querySelectorAll('.category-card');const sectionHeaders=document.querySelectorAll('.articles-title, .main-title, .section-header, .profile-header, .hero-content');articleCards.forEach((card,index)=>{card.classList.add('animate-on-scroll');card.style.animationDelay=`${index*0.1}s`});categoryCards.forEach((card,index)=>{card.classList.add('animate-on-scroll');card.style.animationDelay=`${index*0.1}s`});sectionHeaders.forEach(header=>{header.classList.add('animate-on-scroll')})}function setupCardEffects(){const cards=document.querySelectorAll('.article-card, .category-card');cards.forEach(card=>{card.addEventListener('mouseenter',function(){this.classList.add('hover')});card.addEventListener('mouseleave',function(){this.classList.remove('hover')})})}function animateOnScroll(){const elements=document.querySelectorAll('.animate-on-scroll:not(.animated)');const viewportHeight=window.innerHeight;elements.forEach(element=>{const elementPosition=element.getBoundingClientRect().top;if(elementPosition<viewportHeight-100){element.classList.add('animated')}})}document.addEventListener('DOMContentLoaded',()=>{const smoothScrollLinks=document.querySelectorAll('a[href^="#"]:not(.dropdown-toggle)');smoothScrollLinks.forEach(link=>{link.addEventListener('click',function(e){const targetId=this.getAttribute('href');if(targetId!=='#'){e.preventDefault();const targetElement=document.querySelector(targetId);if(targetElement){window.scrollTo({top:targetElement.offsetTop-80,behavior:'smooth'});const mobileMenuBtn=document.querySelector('.mobile-menu-btn');const nav=document.querySelector('nav');const overlay=document.querySelector('.overlay');if(mobileMenuBtn&&mobileMenuBtn.classList.contains('active')){mobileMenuBtn.classList.remove('active');nav.classList.remove('active');overlay.classList.remove('active');document.body.classList.remove('menu-open')}}}})})}); 